// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Read the export's bills": "in0_Readtheexportsbills", "Read commitments for bills": "in1_Readcommitmentsforbills"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read commitments for bills";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"reserve_body": JSON.stringify({ p_recipe: 'R11.3', p_keys: String(out.keys || '').split('|').filter(Boolean) })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 12: only bills against a commitment count; each bill is counted once (key log).
const bills = $('Read the export\'s bills').first().json.items || [];
const commitments = new Set(($('Read commitments for bills').first().json.items || []).map(c => c.request_id));
const keys = bills.filter(b => commitments.has(b.request_id)).map(b => 'bill:' + b.id);
return keys.length ? [{ json: { keys: keys.join('|') } }] : [];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));

// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read the export's bills": "in1_Readtheexportsbills", "Read commitments for bills": "in2_Readcommitmentsforbills", "Reserve bill keys": "in3_Reservebillkeys"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Reserve bill keys";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// Reserve bill keys: the function's list of new keys, as the n8n rule reads it: {new_keys: 'a|b'}.
const __keys = (DATA['Reserve bill keys'] || [{ json: [] }])[0].json;
DATA['Reserve bill keys'] = [{ json: { new_keys: (Array.isArray(__keys) ? __keys : [])
  .map(k => (k && typeof k === 'object' ? Object.values(k)[0] : k)).filter(Boolean).join('|') } }];
const BODIES = (out) => ({"commitment_q": encodeURIComponent(out.commitment), "reduce_body": JSON.stringify({ billed: out.billed, remaining: out.remaining }), "over_body": JSON.stringify({ recipe: 'R11.3', item: out.request_id, reason: 'bill over commitment', detail: out.detail, owner: $('Config').first().json.budget_owner }), "owner_message": JSON.stringify({ to: $('Config').first().json.budget_owner, subject: 'Bill over its commitment: request ' + out.request_id, text: out.detail }), "done_keys_body": JSON.stringify({ p_recipe: 'R11.3', p_keys: out.keys.split('|'), p_status: 'done', p_result: 'billed ' + out.billed + ', remaining ' + out.remaining }), "failed_keys_body": JSON.stringify({ p_recipe: 'R11.3', p_keys: out.keys.split('|'), p_status: 'failed', p_result: 'write failed' }), "failed_body": JSON.stringify({ recipe: 'R11.3', item: out.request_id, reason: 'write failed', detail: 'Commitment write failed; check the budget list before rerunning', owner: $('Config').first().json.editor }), "log_body": JSON.stringify({ recipe: 'R11.3', item: out.commitment, decision: out.over ? 'bill over commitment' : 'commitment reduced by bills', rules: { amount: out.amount, billed: out.billed, remaining: out.remaining, bills: out.bills } })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 12: reduce each commitment by its new bills; a bill over its commitment by more than the tolerance goes to the budget owner.
const cfg = $('Config').first().json;
const tolerance = Number(cfg.bill_tolerance);
if (!Number.isFinite(tolerance)) throw new Error('Set bill_tolerance in Config to a number of dollars');
const fresh = new Set(String($('Reserve bill keys').first().json.new_keys || '').split('|').filter(Boolean));
const bills = ($('Read the export\'s bills').first().json.items || []).filter(b => fresh.has('bill:' + b.id));
const out = [];
for (const c of $('Read commitments for bills').first().json.items || []) {
  const mine = bills.filter(b => b.request_id === c.request_id);
  if (!mine.length) continue;
  const billed = Number(c.billed || 0) + mine.reduce((s, b) => s + Number(b.amount), 0);
  const remaining = Math.max(0, Number(c.amount) - billed);
  const over = billed > Number(c.amount) + tolerance;
  out.push({ json: { commitment: c.id, request_id: c.request_id, amount: Number(c.amount), billed, remaining, over,
    bills: mine.map(b => b.id), keys: mine.map(b => 'bill:' + b.id).join('|'),
    detail: `Commitment ${c.id}: ${c.amount}; billed ${billed} (${mine.map(b => b.id).join(', ')}); tolerance ${tolerance}` } });
}
return out;
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
